"""
DrugCode DSL - C++20 / OpenMP High-Performance Code Generator
Emits vectorized, multi-threaded C++20 screening workflows.
"""

from typing import List
from drugcode.ir.ir_nodes import (
    IRProgram, IRPipeline, IRNode, IROpType,
    IRDatasetLoad, IRFilter, IRScore, IRRank, IRExport, IRTarget
)
from .base import BaseCodeGen


class CppCodeGen(BaseCodeGen):
    def generate(self, program: IRProgram) -> str:
        lines: List[str] = [
            "// =============================================================================",
            "// Generated by DrugCode: ML-Based Domain-Specific Compiler for Drug Discovery",
            "// Target: C++20 with OpenMP Parallel Screening",
            "// Compile: g++ -O3 -std=c++20 -fopenmp workflow.cpp -o workflow",
            "// =============================================================================",
            "#include <iostream>",
            "#include <fstream>",
            "#include <sstream>",
            "#include <vector>",
            "#include <string>",
            "#include <unordered_map>",
            "#include <algorithm>",
            "#include <chrono>",
            "#include <cmath>",
            "#include <omp.h>",
            "",
            "struct Molecule {",
            "    std::string id;",
            "    std::string name;",
            "    std::string smiles;",
            "    double mw{0.0};",
            "    double logp{0.0};",
            "    int hbd{0};",
            "    int hba{0};",
            "    int rotb{0};",
            "    int aromatic_rings{0};",
            "    double tpsa{0.0};",
            "    double qed{0.0};",
            "    double oral_bioavailability{0.85};",
            "    double synthetic_accessibility{2.5};",
            "    bool herg_inhibition{false};",
            "    double docking_affinity{0.0};",
            "};",
            "",
            "// Fast SMILES property parser",
            "void compute_properties(Molecule& mol) {",
            "    int heavy = 0;",
            "    int total_arom = 0;",
            "    for (char c : mol.smiles) {",
            "        if (c == 'c' || c == 'n' || c == 'o' || c == 's') total_arom++;",
            "        if (c == 'C' || c == 'c') { mol.mw += 12.011; heavy++; mol.logp += 0.15; }",
            "        else if (c == 'O' || c == 'o') { mol.mw += 15.999; heavy++; mol.hba++; mol.tpsa += 9.23; mol.logp -= 0.32; }",
            "        else if (c == 'N' || c == 'n') { mol.mw += 14.007; heavy++; mol.hba++; mol.tpsa += 12.03; mol.logp -= 0.31; }",
            "        else if (c == 'S' || c == 's') { mol.mw += 32.065; heavy++; mol.tpsa += 25.30; mol.logp += 0.38; }",
            "    }",
            "    mol.aromatic_rings = static_cast<int>(std::round(total_arom / 6.0));",
            "    int implicit_h = static_cast<int>(heavy * 1.2);",
            "    mol.mw += implicit_h * 1.008;",
            "    mol.logp += implicit_h * 0.112;",
            "    mol.rotb = static_cast<int>(std::max(0.0, (heavy - total_arom) * 0.3));",
            "    mol.synthetic_accessibility = 1.0 + mol.rotb * 0.25 + mol.aromatic_rings * 0.3;",
            "    mol.herg_inhibition = (mol.logp > 3.5 && mol.mw > 400.0) || (mol.aromatic_rings >= 3 && mol.logp > 3.0);",
            "    mol.oral_bioavailability = std::max(0.1, 0.95 - (mol.mw > 500.0 ? 0.2 : 0.0) - (mol.logp > 5.0 ? 0.2 : 0.0));",
            "    double d_mw = 1.0 / (1.0 + std::exp((mol.mw - 380.0) / 45.0));",
            "    double d_lp = std::exp(-0.5 * std::pow((mol.logp - 2.5) / 1.8, 2));",
            "    mol.qed = std::sqrt(std::max(1e-5, d_mw * d_lp));",
            "}",
            "",
            "// Empirical docking scoring with conformational exploration",
            "double score_docking(const Molecule& mol, double exhaustiveness) {",
            "    double dg = -3.5 - 0.35 * std::min(5.0, std::max(0.5, mol.logp));",
            "    dg -= 1.15 * mol.aromatic_rings;",
            "    dg -= 0.85 * (mol.hbd + mol.hba);",
            "    dg += 0.28 * mol.rotb;",
            "    double best_pose = 0.0;",
            "    for (int step = 0; step < static_cast<int>(exhaustiveness * 40); ++step) {",
            "        double theta = (step * 3.14159265) / 20.0;",
            "        double p_val = std::sin(theta * 2.0) * 0.12 * (1.0 + std::min(8, mol.rotb) * 0.08);",
            "        if (p_val < best_pose) best_pose = p_val;",
            "    }",
            "    dg += best_pose - 0.15 * std::log(std::max(1.0, exhaustiveness));",
            "    return dg;",
            "}",
            ""
        ]

        # Emit main function running pipelines
        lines.append("int main() {")
        lines.append("    std::cout << \"[DrugCode C++20 Runtime Initialized with \" << omp_get_max_threads() << \" threads]\\n\";")
        lines.append("    auto start_all = std::chrono::high_resolution_clock::now();")
        lines.append("")

        for pipe_name, pipeline in program.pipelines.items():
            lines.append(f"    // Pipeline: {pipe_name}")
            for nid in pipeline.execution_order:
                node = pipeline.nodes[nid]
                if isinstance(node, IRDatasetLoad):
                    lines.append(f"    std::vector<Molecule> stream_{node.id};")
                    lines.append(f"    std::ifstream file_{node.id}(\"{node.filepath}\");")
                    lines.append(f"    std::string line_{node.id};")
                    lines.append(f"    while (std::getline(file_{node.id}, line_{node.id})) {{")
                    lines.append(f"        if (line_{node.id}.empty() || line_{node.id}[0] == '#') continue;")
                    lines.append(f"        std::istringstream iss(line_{node.id});")
                    lines.append(f"        Molecule m; iss >> m.smiles >> m.id >> m.name;")
                    lines.append(f"        compute_properties(m);")
                    lines.append(f"        stream_{node.id}.push_back(m);")
                    lines.append("    }")
                    lines.append(f"    std::cout << \"[{node.id}] Loaded \" << stream_{node.id}.size() << \" molecules\\n\";\n")

                elif isinstance(node, IRFilter):
                    in_s = f"stream_{node.inputs[0]}"
                    out_s = f"stream_{node.id}"
                    lines.append(f"    std::vector<Molecule> {out_s};")
                    conds = []
                    for p in node.predicates:
                        field_map = {
                            "MW": "m.mw", "LogP": "m.logp", "HBD": "m.hbd", "HBA": "m.hba",
                            "RotatableBonds": "m.rotb", "AromaticRings": "m.aromatic_rings",
                            "TPSA": "m.tpsa", "QED": "m.qed",
                            "OralBioavailability": "m.oral_bioavailability",
                            "SyntheticAccessibility": "m.synthetic_accessibility",
                            "hERG_Inhibition": "m.herg_inhibition"
                        }
                        cpp_field = field_map.get(p.property_name, "m.mw")
                        cpp_th = "true" if p.threshold is True else ("false" if p.threshold is False else str(p.threshold))
                        conds.append(f"({cpp_field} {p.operator} {cpp_th})")
                    cond_expr = " && ".join(conds) if conds else "true"
                    lines.append(f"    for (const auto& m : {in_s}) {{")
                    lines.append(f"        if ({cond_expr}) {out_s}.push_back(m);")
                    lines.append("    }")
                    lines.append(f"    std::cout << \"[{node.id}] Filtered \" << {in_s}.size() << \" -> \" << {out_s}.size() << \"\\n\";\n")

                elif isinstance(node, IRScore):
                    in_s = f"stream_{node.inputs[0]}"
                    out_s = f"stream_{node.id}"
                    lines.append(f"    std::vector<Molecule> {out_s};")
                    lines.append(f"    #pragma omp parallel for")
                    lines.append(f"    for (size_t i = 0; i < {in_s}.size(); ++i) {{")
                    lines.append(f"        {in_s}[i].docking_affinity = score_docking({in_s}[i], {node.exhaustiveness});")
                    lines.append("    }")
                    lines.append(f"    for (const auto& m : {in_s}) {{")
                    cutoff = node.affinity_threshold if node.affinity_threshold is not None else 0.0
                    lines.append(f"        if (m.docking_affinity <= {cutoff}) {out_s}.push_back(m);")
                    lines.append("    }")
                    lines.append(f"    std::cout << \"[{node.id}] Docked \" << {in_s}.size() << \" -> \" << {out_s}.size() << \"\\n\";\n")

                elif isinstance(node, IRRank):
                    in_s = f"stream_{node.inputs[0]}"
                    out_s = f"stream_{node.id}"
                    lines.append(f"    std::vector<Molecule> {out_s} = {in_s};")
                    lines.append(f"    std::sort({out_s}.begin(), {out_s}.end(), [](const Molecule& a, const Molecule& b) {{ return a.docking_affinity < b.docking_affinity; }});")
                    if node.top_k is not None:
                        lines.append(f"    if ({out_s}.size() > {node.top_k}) {out_s}.resize({node.top_k});")
                    lines.append(f"    std::cout << \"[{node.id}] Ranked top \" << {out_s}.size() << \"\\n\";\n")

                elif isinstance(node, IRExport):
                    in_s = f"stream_{node.inputs[0]}"
                    lines.append(f"    std::ofstream out_file(\"{node.destination_path}\");")
                    lines.append(f"    out_file << \"id,name,smiles,MW,LogP,HBD,HBA,RotatableBonds,TPSA,QED,OralBioavailability,SyntheticAccessibility,hERG_Inhibition,docking_affinity\\n\";")
                    lines.append(f"    for (const auto& m : {in_s}) {{")
                    lines.append(f"        out_file << m.id << \",\" << m.name << \",\" << m.smiles << \",\" << m.mw << \",\" << m.logp << \",\" << m.hbd << \",\" << m.hba << \",\" << m.rotb << \",\" << m.tpsa << \",\" << m.qed << \",\" << m.oral_bioavailability << \",\" << m.synthetic_accessibility << \",\" << (m.herg_inhibition ? \"True\" : \"False\") << \",\" << m.docking_affinity << \"\\n\";")
                    lines.append("    }")
                    lines.append(f"    std::cout << \"[{node.id}] Exported results to {node.destination_path}\\n\";\n")

        lines.append("    auto end_all = std::chrono::high_resolution_clock::now();")
        lines.append("    std::chrono::duration<double, std::milli> ms = end_all - start_all;")
        lines.append("    std::cout << \"Total execution time: \" << ms.count() << \" ms\\n\";")
        lines.append("    return 0;")
        lines.append("}")

        return "\n".join(lines)
